7. public class TicketClassifierService
8. {
9.     private readonly MLContext _mlContext;
10.     private readonly ITransformer _model;
11.     private readonly PredictionEngine<TicketInput, TicketPrediction> _predictionEngine;
12.     private readonly EvaluationMetrics _metrics;
13.     private readonly string[] _categoryLabels;
14. 
15.     public TicketClassifierService(string dataPath)
16.     {
17.         _mlContext = new MLContext(seed: 42);
18. 
19.         var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
20.             dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
21. 
22.         var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
23.             .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
24.             .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
25.             .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
26.             .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
27.             .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
28. 
29.         // Train with cross-validation for metrics
30.         var cvResults = _mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3);
31. 
32.         _metrics = new EvaluationMetrics
33.         {
34.             MacroAccuracy = cvResults.Average(r => r.Metrics.MacroAccuracy),
35.             MicroAccuracy = cvResults.Average(r => r.Metrics.MicroAccuracy),
36.             LogLoss = cvResults.Average(r => r.Metrics.LogLoss),
37.             LogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction)
38.         };
39. 
40.         // Train final model on all data
41.         _model = pipeline.Fit(dataView);
42.         _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);
43. 
44.         // Extract category labels from the trained model's key-to-value mapping
45.         var transformedData = _model.Transform(dataView);
46.         var labelKeyColumn = transformedData.Schema["Label"];
47.         var keyValues = new VBuffer<ReadOnlyMemory<char>>();
48.         labelKeyColumn.GetKeyValues(ref keyValues);
49.         _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
50.     }
51. 
52.     public PredictionResponse Predict(TicketRequest request)
53.     {
54.         var input = new TicketInput
55.         {
56.             Subject = request.Subject,
57.             Description = request.Description,
58.             Priority = request.Priority
59.         };
60. 
61.         var prediction = _predictionEngine.Predict(input);
62. 
63.         var scores = new Dictionary<string, float>();
64.         for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
65.         {
66.             scores[_categoryLabels[i]] = prediction.Score[i];
67.         }
